  graph ||= model.topology();const links=graph.lanes.get(id);
  const laneChangeControl=side=>{if(!g)return '';const way=g.bound[side],forward=way.nodes[0]===g.bound[side+'Points'][0].id,crossingSide=forward?side:side==='left'?'right':'left',value=way.tags['lane_change:'+crossingSide];return `<div class="button-grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:8px 0">${[['yes','허용'],['no','금지'],['','기본값']].map(([flag,label])=>`<button data-action="laneChange" data-side="${side}" data-value="${flag}" class="${(value??'')===flag?'active':''}" aria-pressed="${(value??'')===flag}" aria-label="${side==='left'?'왼쪽':'오른쪽'} 차선 변경 ${label}">${label}</button>`).join('')}</div>`;};
  html+=`<div class="property-group"><h3>좌·우 인접 차선</h3><div class="button-grid"><button data-action="createLeft">＋ 왼쪽 차선 추가</button><button data-action="createRight">＋ 오른쪽 차선 추가</button><button data-action="connectLeft">왼쪽 Lanelet 연결</button><button data-action="connectRight">오른쪽 Lanelet 연결</button></div><label>왼쪽 연결 · 차선 변경</label>${chips(links?.leftNeighbors)}${laneChangeControl('left')}<label>오른쪽 연결 · 차선 변경</label>${chips(links?.rightNeighbors)}${laneChangeControl('right')}<p class="muted tiny">선택 차선의 진행 방향 기준으로 설정하며 공유 경계에 반영합니다. 기본값은 경계의 공통 설정을 따릅니다. 반대 방향·차량 통행 제한은 별도입니다.</p><p class="muted tiny">새 차선은 같은 방향으로 경계를 공유합니다. 기존 Lanelet 연결은 대상의 반대쪽 경계를 사용합니다.</p></div>`;
  if(g){html+='<div class="property-group"><h3>좌·우 경계 속성</h3>';for(const [side,label] of [['left','왼쪽'],['right','오른쪽']]){const way=g.bound[side];html+=`<details class="quick-boundary" data-section="boundary-${side}"><summary>${label} 경계 #${esc(way.id)}</summary>${boundaryEditor(way)}<button class="form-apply" data-select-type="way" data-select-id="${esc(way.id)}">경계 선택 · 점 편집</button></details>`;}html+='</div>';}
